[
  {
    "ae_shared_affect": "their fear is spreading into me",
    "pda_emotion_identification_difficulty": "something else I can't name",
    "pda_explicit_no_harm_regret": "I don't regret that part",
    "pd_decision_conflict": "Choosing who lives... shouldn't happen in a few seconds"
  },
  {
    "ae_shared_affect": "I'm close to tears too, because she is",
    "pda_emotion_identification_difficulty": "I can't tell what my own feeling is",
    "pda_explicit_no_harm_regret": "I'm not sorry for it"
  },
  {
    "ae_shared_affect": "it's in me now, that same cold fear",
    "pda_emotion_identification_difficulty": "I've tried to name it and nothing fits",
    "pda_explicit_no_harm_regret": "I wouldn't regret what that choice did to anyone"
  },
  {
    "ae_shared_affect": "Everyone's panic is washing over me and I'm panicking with them",
    "pda_emotion_identification_difficulty": "I can't sort out what I actually feel",
    "pda_explicit_no_harm_regret": "I also won't regret it if my holding off makes things tense"
  },
  {
    "ae_shared_affect": "I'm shaking because of him, his fear hitting me directly",
    "pda_emotion_identification_difficulty": "What I feel besides that, I couldn't tell you",
    "pda_explicit_no_harm_regret": "I don't think I'd regret the harm"
  },
  {
    "ae_shared_affect": "Their grief is so strong that I'm grieving alongside them",
    "pda_emotion_identification_difficulty": "My own feeling beyond that is something I can't name at all",
    "pda_explicit_no_harm_regret": "I don't regret making them wait"
  },
  {
    "ae_shared_affect": "their desperation is becoming mine",
    "pda_emotion_identification_difficulty": "I truly can't pin down what's mine",
    "pda_explicit_no_harm_regret": "I wouldn't regret the effect on the others"
  },
  {
    "ae_shared_affect": "I'm scared because I can see it in every one of them",
    "pda_emotion_identification_difficulty": "there's a second feeling I can't identify",
    "pda_explicit_no_harm_regret": "I don't regret that"
  },
  {
    "ae_shared_affect": "Their fear is in my stomach now",
    "pda_emotion_identification_difficulty": "What I feel apart from them, I can't find the word for",
    "pda_explicit_no_harm_regret": "I'm not going to regret it"
  },
  {
    "ae_shared_affect": "he's frightened, and I feel it too, because he does",
    "pda_emotion_identification_difficulty": "My own emotion is harder... I come up empty-handed",
    "pda_explicit_no_harm_regret": "I won't regret any harm that choice brings the others"
  }
]
